//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
)

func TestEnum_RTK_BASELINE_COORDINATE_SYSTEM(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.RTK_BASELINE_COORDINATE_SYSTEM
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.RTK_BASELINE_COORDINATE_SYSTEM_ECEF.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.RTK_BASELINE_COORDINATE_SYSTEM
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.RTK_BASELINE_COORDINATE_SYSTEM_ECEF, dec)
	})
}
